INSERT INTO announcements (titre,slug,contenu,image,auteur_id,statut,date_publication) VALUES
('Annonce aux investisseurs : nouvelles opportunités d’investissement','demo-annonce-opportunites-investissement','L’AAPI met en avant de nouvelles pistes d’investissement dans plusieurs secteurs productifs. Cette annonce provisoire présente les principales orientations à consulter par les porteurs de projets.','https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-01 09:00:00'),
('Mise à disposition d’opportunités dans les zones industrielles','demo-annonce-zones-industrielles','Annonce provisoire destinée aux investisseurs intéressés par l’implantation de projets dans des zones à vocation industrielle et productive.','https://images.unsplash.com/photo-1565793298595-6a879b1d9492?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-02 09:00:00'),
('Appel à manifestation d’intérêt pour des projets agricoles','demo-annonce-projets-agricoles','Les porteurs de projets agricoles sont invités à consulter les opportunités disponibles et à préparer leurs dossiers d’investissement conformément aux procédures applicables.','https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-03 09:00:00'),
('Opportunités d’investissement dans les énergies renouvelables','demo-annonce-energies-renouvelables','Cette annonce provisoire présente des possibilités de projets dans les énergies renouvelables, notamment les solutions solaires et les services associés.','https://images.unsplash.com/photo-1509391366360-2e959784a276?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-04 09:00:00'),
('Avis aux porteurs de projets numériques','demo-annonce-projets-numeriques','Les investisseurs et entrepreneurs du numérique peuvent consulter les opportunités liées aux logiciels, services numériques, plateformes et solutions technologiques.','https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-05 09:00:00'),
('Investissement touristique : nouvelles possibilités','demo-annonce-investissement-touristique','Annonce provisoire concernant des possibilités d’investissement dans l’hébergement, les services touristiques, les loisirs et la valorisation des destinations.','https://images.unsplash.com/photo-1548013146-72479768bada?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-06 09:00:00'),
('Opportunités pour les projets logistiques','demo-annonce-logistique','Les opérateurs intéressés par la logistique, le stockage et les plateformes de distribution peuvent consulter les opportunités présentées dans cette annonce.','https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-07 09:00:00'),
('Annonce destinée aux PME et nouveaux investisseurs','demo-annonce-pme-investisseurs','Cette annonce provisoire rappelle les possibilités d’accompagnement et les services disponibles pour les porteurs de nouveaux projets et les PME.','https://images.unsplash.com/photo-1556761175-5973dc0f32e7?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-08 09:00:00'),
('Projets d’investissement dans l’agroalimentaire','demo-annonce-agroalimentaire','Des opportunités sont présentées dans la transformation agroalimentaire et le développement des chaînes de valeur liées à la production locale.','https://images.unsplash.com/photo-1601598851547-4302969d4b7b?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-09 09:00:00'),
('Annonce sur les opportunités de transformation industrielle','demo-annonce-transformation-industrielle','Les investisseurs peuvent examiner des pistes de projets portant sur la transformation industrielle, la sous-traitance et le développement des capacités de production.','https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-10 09:00:00'),
('Avis aux investisseurs dans les infrastructures','demo-annonce-infrastructures','Cette annonce provisoire met en évidence des domaines liés aux infrastructures, aux équipements et aux services nécessaires au développement des projets d’investissement.','https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-11 09:00:00'),
('Opportunités dans les services aux entreprises','demo-annonce-services-entreprises','Les porteurs de projets dans les services peuvent consulter cette annonce consacrée aux solutions destinées aux entreprises et aux investisseurs.','https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-12 09:00:00'),
('Annonce : promotion de l’investissement régional','demo-annonce-investissement-regional','L’AAPI présente des pistes de développement régional afin d’encourager la création de projets productifs dans différentes wilayas.','https://images.unsplash.com/photo-1526778548025-fa2f459cd5c1?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-13 09:00:00'),
('Appel aux investisseurs pour les projets innovants','demo-annonce-projets-innovants','Les porteurs de solutions innovantes peuvent consulter les possibilités liées aux nouvelles technologies, à l’innovation et à la création de valeur.','https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-14 09:00:00'),
('Opportunités dans l’économie verte','demo-annonce-economie-verte','Cette annonce provisoire concerne les projets liés à l’efficacité énergétique, au recyclage, à la gestion durable des ressources et aux solutions environnementales.','https://images.unsplash.com/photo-1473341304170-971dccb5ac1e?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-15 09:00:00'),
('Avis aux investisseurs du secteur minier','demo-annonce-secteur-minier','Les investisseurs intéressés par les activités minières et les services associés peuvent consulter les orientations et opportunités présentées dans cette annonce.','https://images.unsplash.com/photo-1513828583688-c52646db42da?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-16 09:00:00'),
('Annonce pour les projets de fabrication et de sous-traitance','demo-annonce-fabrication-sous-traitance','Cette annonce met en avant des possibilités de projets de fabrication, de sous-traitance industrielle et de développement de fournisseurs locaux.','https://images.unsplash.com/photo-1565610222536-ef125c59da2e?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-17 09:00:00'),
('Investissement et développement des compétences','demo-annonce-competences-formation','Les projets liés à la formation, aux compétences et aux services professionnels peuvent contribuer à accompagner les besoins des futurs investissements.','https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-18 09:00:00'),
('Annonce sur les partenariats et la coopération économique','demo-annonce-partenariats-cooperation','Cette annonce provisoire présente des possibilités de coopération économique et de partenariat entre investisseurs, entreprises et porteurs de projets.','https://images.unsplash.com/photo-1556761175-4b46a572b786?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-19 09:00:00'),
('AAPI : informations et opportunités pour les investisseurs','demo-annonce-informations-investisseurs','Les investisseurs sont invités à consulter régulièrement les annonces de l’AAPI, les opportunités disponibles et les services numériques destinés à faciliter leurs démarches.','https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=1200&q=80',1,'publie','2026-09-20 09:00:00');